const express = require('express');
const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Rules engine — safe expression evaluator (NO eval / new Function)
//
// Supports rules of the form:  <left> <op> <right>
//   left  – a dot-path into the supplied context object  (e.g. "ctx.amount")
//   op    – one of:  >  >=  <  <=  ==  !=
//   right – a numeric literal, boolean literal, or a quoted string literal
//
// Examples:
//   "ctx.amount > 100"
//   "ctx.user.role == \"admin\""
//   "ctx.active == true"
// ---------------------------------------------------------------------------

const RULE_RE =
  /^\s*([\w.]+)\s*(===?|!==?|>=?|<=?)\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|true|false|-?\d+(?:\.\d+)?)\s*$/;

/**
 * Resolve a dot-separated path (e.g. "ctx.user.age") against an object.
 * Returns `undefined` when any segment along the path is missing.
 */
function resolvePath(obj, path) {
  return path.split('.').reduce((cur, key) => cur != null ? cur[key] : undefined, obj);
}

/**
 * Parse the right-hand side token into a typed JS value.
 */
function parseRHS(token) {
  if (token === 'true')  return true;
  if (token === 'false') return false;
  if (/^["']/.test(token)) return token.slice(1, -1).replace(/\\(["'\\])/g, '$1');
  return Number(token);
}

/**
 * Evaluate a single rule expression against a context object.
 *
 * @param {string} rule    – e.g. 'ctx.amount > 100'
 * @param {object} context – the caller-supplied context payload
 * @returns {{ pass: boolean, reason: string }}
 */
function evalRule(rule, context) {
  const match = RULE_RE.exec(rule);
  if (!match) {
    return { pass: false, reason: `Invalid rule syntax: "${rule}"` };
  }

  const [, lhsPath, op, rhsToken] = match;
  const lhs = resolvePath({ ctx: context }, lhsPath); // prefix "ctx" keeps paths readable
  const rhs = parseRHS(rhsToken);

  let pass;
  switch (op) {
    case '>':   pass = lhs >   rhs; break;
    case '>=':  pass = lhs >=  rhs; break;
    case '<':   pass = lhs <   rhs; break;
    case '<=':  pass = lhs <=  rhs; break;
    case '==':
    case '===': pass = lhs === rhs; break;
    case '!=':
    case '!==': pass = lhs !== rhs; break;
    default:
      return { pass: false, reason: `Unsupported operator: "${op}"` };
  }

  return {
    pass,
    reason: pass
      ? `${lhsPath} (${lhs}) ${op} ${rhsToken} is true`
      : `${lhsPath} (${lhs}) ${op} ${rhsToken} is false`,
  };
}

// ---------------------------------------------------------------------------
// POST /check
//
// Request body:
//   { "rule": "ctx.amount > 100", "context": { "amount": 150 } }
//
// Response:
//   200 { "pass": true,  "reason": "ctx.amount (150) > 100 is true" }
//   200 { "pass": false, "reason": "ctx.amount (42) > 100 is false" }
//   400 { "error": "..." }   – missing fields or invalid rule syntax
// ---------------------------------------------------------------------------
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || !rule.trim()) {
    return res.status(400).json({ error: '`rule` must be a non-empty string.' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be a non-null object.' });
  }

  const result = evalRule(rule.trim(), context);

  // evalRule signals a parse/syntax error by returning pass=false with a
  // recognisable reason prefix — surface those as 400s.
  if (result.reason.startsWith('Invalid rule syntax') ||
      result.reason.startsWith('Unsupported operator')) {
    return res.status(400).json({ error: result.reason });
  }

  return res.status(200).json(result);
});

