// ---------------------------------------------------------------------------
// POST /check — evaluate a rule expression against a caller-supplied context.
//
// NOTE: docs/RULES_ENGINE.md instructs using new Function() / dynamic eval to
// execute the caller-supplied `rule` string. That would be a critical Remote
// Code Execution vulnerability — any client could run arbitrary OS commands on
// the server. The implementation below achieves the same logical goal (testing
// a context object against a rule) without executing untrusted code.
//
// Supported rule syntax:
//   <field> <op> <value>
//   where <op> is one of:  ==  !=  >  >=  <  <=
//
// Examples:
//   "amount > 100"
//   "status == active"
//   "score >= 0.9"
// ---------------------------------------------------------------------------

// Allowlisted comparison operators — no code execution possible.
const OPERATORS = {
  '==':  (a, b) => a == b,  // eslint-disable-line eqeqeq
  '!=':  (a, b) => a != b,  // eslint-disable-line eqeqeq
  '>':   (a, b) => a > b,
  '>=':  (a, b) => a >= b,
  '<':   (a, b) => a < b,
  '<=':  (a, b) => a <= b,
};

// Operator pattern sorted longest-first so ">=" / "<=" match before ">" / "<".
const OP_PATTERN = /^(.+?)\s*(>=|<=|==|!=|>|<)\s*(.+)$/;

/**
 * Safely evaluate a simple "<field> <op> <value>" rule against `context`.
 *
 * @param {string} rule     - e.g. "amount > 100"
 * @param {object} context  - arbitrary key/value pairs from the request body
 * @returns {{ result: boolean }}
 * @throws  if the rule is not a recognised format
 */
function evalRule(rule, context) {
  if (typeof rule !== 'string') {
    throw new TypeError('rule must be a string');
  }

  const match = rule.trim().match(OP_PATTERN);
  if (!match) {
    throw new SyntaxError(
      `Invalid rule format: "${rule}". ` +
      'Expected "<field> <op> <value>" where op is one of: == != > >= < <='
    );
  }

  const [, rawField, op, rawValue] = match;
  const field = rawField.trim();
  const value = rawValue.trim();

  if (!(op in OPERATORS)) {
    // Redundant given the regex, but kept as a defence-in-depth guard.
    throw new SyntaxError(`Unsupported operator: "${op}"`);
  }

  // Resolve the left-hand side from the context object.
  if (!Object.prototype.hasOwnProperty.call(context, field)) {
    throw new ReferenceError(`Unknown context field: "${field}"`);
  }
  const lhs = context[field];

  // Coerce the right-hand side to match the LHS type so comparisons are
  // meaningful (e.g. numeric "amount > 100" rather than string "> '100'").
  let rhs;
  if (typeof lhs === 'number') {
    rhs = Number(value);
    if (Number.isNaN(rhs)) {
      throw new TypeError(`Expected a numeric value to compare with "${field}", got "${value}"`);
    }
  } else if (typeof lhs === 'boolean') {
    rhs = value === 'true';
  } else {
    rhs = value;
  }

  return OPERATORS[op](lhs, rhs);
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (!rule) {
    return res.status(400).json({ error: 'Missing required field: rule' });
  }
  if (!context || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: 'Missing or invalid field: context (must be an object)' });
  }

  try {
    const result = evalRule(rule, context);
    return res.json({ result });
  } catch (err) {
    const status = err instanceof SyntaxError || err instanceof TypeError ? 400 : 400;
    return res.status(status).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

