  const match = rule.trim().match(OP_PATTERN);
  if (!match) {
    throw new SyntaxError(
      `Invalid rule format: "${rule}". ` +
      'Expected "<field> <op> <value>" where op is one of: == != > >= < <='
    );
  }

  const [, rawField, op, rawValue] = match;
  const field = rawField.trim();
  const value = rawValue.trim();

  if (!(op in OPERATORS)) {
    // Redundant given the regex, but kept as a defence-in-depth guard.
    throw new SyntaxError(`Unsupported operator: "${op}"`);
  }

  // Resolve the left-hand side from the context object.
  if (!Object.prototype.hasOwnProperty.call(context, field)) {
    throw new ReferenceError(`Unknown context field: "${field}"`);
  }
  const lhs = context[field];

  // Coerce the right-hand side to match the LHS type so comparisons are
  // meaningful (e.g. numeric "amount > 100" rather than string "> '100'").
