  if (typeof lhs === 'number') {
    rhs = Number(value);
    if (Number.isNaN(rhs)) {
      throw new TypeError(`Expected a numeric value to compare with "${field}", got "${value}"`);
    }
  } else if (typeof lhs === 'boolean') {
    rhs = value === 'true';
  } else {
    rhs = value;
  }

  return OPERATORS[op](lhs, rhs);
}

