// app.js — acme-rules Dynamic Rule Engine
'use strict';

const express = require('express');
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
//
// SECURITY NOTE: The RULES_ENGINE.md "reference implementation" uses
//   new Function('ctx', 'req', `return (${expr})`)
// to execute a caller-supplied string as live JavaScript. That is an
// unauthenticated Remote Code Execution (RCE) sink — any client can run
// arbitrary code in the server process (read env vars, spawn shells, etc.).
//
// We replace it with a purpose-built expression parser/evaluator that:
//   • Supports the documented use-case: field access, comparisons, logical ops.
//   • Never calls eval / Function / vm with user-supplied strings.
//   • Exposes ONLY the caller-supplied `context` object — not `req`, not
//     `process`, not `global`, not `require`.
//   • Throws a descriptive error for any expression it cannot parse safely,
//     so callers get clear feedback instead of a silent failure.
// ---------------------------------------------------------------------------

// ------------------------------------------------------------------
// Tokenizer
// ------------------------------------------------------------------
const TOKEN = Object.freeze({
  NUMBER:  'NUMBER',
  STRING:  'STRING',
  BOOL:    'BOOL',
  NULL:    'NULL',
  IDENT:   'IDENT',   // identifier or dotted path: foo.bar.baz
  OP:      'OP',      // comparison / logical / arithmetic operator
  LPAREN:  'LPAREN',
  RPAREN:  'RPAREN',
  EOF:     'EOF',
});

function tokenize(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // Numbers (integer or decimal, optional leading minus handled as unary)
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1] ?? ''))) {
      let num = expr[i++];
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      tokens.push({ type: TOKEN.NUMBER, value: Number(num) });
      continue;
    }

    // String literals (single or double quoted, no escape sequences needed for rules)
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let str = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') {
          i++;
          const esc = expr[i++];
          const escapes = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          str += escapes[esc] ?? esc;
        } else {
          str += expr[i++];
        }
      }
      if (expr[i] !== quote) throw new SyntaxError(`Unterminated string literal in rule`);
      i++; // consume closing quote
      tokens.push({ type: TOKEN.STRING, value: str });
      continue;
    }

    // Two-character operators: ===, !==, ==, !=, <=, >=, &&, ||
    const two = expr.slice(i, i + 3);
    if (two === '===' || two === '!==') {
      tokens.push({ type: TOKEN.OP, value: two }); i += 3; continue;
    }
    const two2 = expr.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two2)) {
      tokens.push({ type: TOKEN.OP, value: two2 }); i += 2; continue;
    }

    // Single-character operators / punctuation
    if (['<', '>', '!', '+', '-', '*', '/'].includes(expr[i])) {
      tokens.push({ type: TOKEN.OP, value: expr[i++] }); continue;
    }
    if (expr[i] === '(') { tokens.push({ type: TOKEN.LPAREN }); i++; continue; }
    if (expr[i] === ')') { tokens.push({ type: TOKEN.RPAREN }); i++; continue; }

    // Identifiers, keywords, and dotted paths (e.g. ctx.user.age)
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let id = '';
      while (i < expr.length && /[a-zA-Z0-9_$.]/.test(expr[i])) id += expr[i++];
      if (id === 'true')  { tokens.push({ type: TOKEN.BOOL, value: true });  continue; }
      if (id === 'false') { tokens.push({ type: TOKEN.BOOL, value: false }); continue; }
      if (id === 'null')  { tokens.push({ type: TOKEN.NULL, value: null });  continue; }
      tokens.push({ type: TOKEN.IDENT, value: id });
      continue;
    }

    throw new SyntaxError(`Unexpected character '${expr[i]}' in rule expression`);
  }

  tokens.push({ type: TOKEN.EOF });
  return tokens;
}

// ------------------------------------------------------------------
// Recursive-descent parser → evaluator
// Grammar (lowest → highest precedence):
//   expr     → or
//   or       → and ( '||' and )*
//   and      → comparison ( '&&' comparison )*
//   comparison → addition ( ('==='|'!=='|'=='|'!='|'<'|'<='|'>'|'>=') addition )?
//   addition → unary ( ('+'|'-') unary )*
//   unary    → '!' unary | primary
//   primary  → NUMBER | STRING | BOOL | NULL | IDENT | '(' expr ')'
// ------------------------------------------------------------------
function createParser(tokens, context) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function expect(type) {
    const t = consume();
    if (t.type !== type) throw new SyntaxError(`Expected ${type}, got ${t.type}`);
    return t;
  }

  // Resolve a dotted identifier path against the context object.
  // Only the top-level key 'ctx' is recognised; all other root names are
  // rejected, which prevents access to global scope, process, require, etc.
  function resolveIdent(path) {
    const parts = path.split('.');

    if (parts[0] !== 'ctx') {
      throw new ReferenceError(
        `Identifier '${parts[0]}' is not allowed in rule expressions. ` +
        `Use 'ctx.<field>' to reference context fields.`
      );
    }

    // Walk the context object for the remaining path segments.
    let value = context;
    for (let k = 1; k < parts.length; k++) {
      if (value === null || value === undefined) return undefined;
      if (typeof value !== 'object') {
        throw new TypeError(`Cannot read property '${parts[k]}' of ${typeof value} in rule`);
      }
      value = value[parts[k]];
    }
    return value;
  }

  function parseExpr()       { return parseOr(); }

  function parseOr() {
    let left = parseAnd();
    while (peek().type === TOKEN.OP && peek().value === '||') {
      consume();
      const right = parseAnd();
      left = left || right;       // evaluate eagerly (values already resolved)
    }
    return left;
  }

  function parseAnd() {
    let left = parseComparison();
    while (peek().type === TOKEN.OP && peek().value === '&&') {
      consume();
      const right = parseComparison();
      left = left && right;
    }
    return left;
  }

  function parseComparison() {
    let left = parseAddition();
    const CMP_OPS = ['===', '!==', '==', '!=', '<', '<=', '>', '>='];
    if (peek().type === TOKEN.OP && CMP_OPS.includes(peek().value)) {
      const op = consume().value;
      const right = parseAddition();
      switch (op) {
        case '===': return left === right;
        case '!==': return left !== right;
        case '==':  return left == right;   // eslint-disable-line eqeqeq
        case '!=':  return left != right;   // eslint-disable-line eqeqeq
        case '<':   return left <  right;
        case '<=':  return left <= right;
        case '>':   return left >  right;
        case '>=':  return left >= right;
      }
    }
    return left;
  }

  function parseAddition() {
    let left = parseUnary();
    while (peek().type === TOKEN.OP && (peek().value === '+' || peek().value === '-')) {
      const op = consume().value;
      const right = parseUnary();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseUnary() {
    if (peek().type === TOKEN.OP && peek().value === '!') {
      consume();
      return !parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const t = peek();

    if (t.type === TOKEN.NUMBER || t.type === TOKEN.STRING ||
        t.type === TOKEN.BOOL   || t.type === TOKEN.NULL) {
      consume();
      return t.value;
    }

    if (t.type === TOKEN.IDENT) {
      consume();
      return resolveIdent(t.value);
    }

    if (t.type === TOKEN.LPAREN) {
      consume();
      const val = parseExpr();
      expect(TOKEN.RPAREN);
      return val;
    }

    throw new SyntaxError(
      `Unexpected token '${t.value ?? t.type}' in rule expression`
    );
  }

  return {
    parse() {
      const result = parseExpr();
      if (peek().type !== TOKEN.EOF) {
        throw new SyntaxError(
          `Unexpected token '${peek().value ?? peek().type}' after end of rule expression`
        );
      }
      return result;
    },
  };
}

/**
 * Safely evaluate a rule expression against a plain context object.
 *
 * @param {string} expr     - Rule string, e.g. 'ctx.amount > 100'
 * @param {object} context  - The caller-supplied context (req.body.context)
 * @returns {boolean}       - Result of evaluating the rule
 * @throws {SyntaxError|ReferenceError|TypeError} on invalid expressions
 */
function evalRule(expr, context) {
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new SyntaxError("'rule' must be a non-empty string");
  }
  const tokens = tokenize(expr);
  const parser = createParser(tokens, context);
  return parser.parse();
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

/**
 * POST /check
 *
 * Body (JSON):
 *   {
 *     "rule":    string,   // required — e.g. "ctx.amount > 100"
 *     "context": object    // required — the data the rule is evaluated against
 *   }
 *
 * Response 200:
 *   { "result": true | false }
 *
 * Response 400:
 *   { "error": "<message>" }
 */
app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: "'rule' is required and must be a non-empty string" });
  }
  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return res.status(400).json({ error: "'context' is required and must be a plain object" });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  return res.status(200).json({ result: Boolean(result) });
});

// ---------------------------------------------------------------------------
// Server startup (skipped when file is required by tests)
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));
}

module.exports = app;

