/**
 * acme-rules — Dynamic Rule Engine
 *
 * POST /check evaluates a structured rule expression against a caller-supplied
 * context object.  Rules are intentionally restricted to a safe, declarative
 * subset rather than executing arbitrary JS via eval / new Function, which
 * would allow remote code execution (RCE), data exfiltration, and denial-of-
 * service attacks from any caller that can reach this endpoint.
 *
 * Supported rule shape (JSON):
 *   { "field": "ctx.amount", "op": ">",  "value": 100 }
 *   { "field": "ctx.role",   "op": "==", "value": "admin" }
 *
 * Supported operators: ==  !=  >  >=  <  <=  contains  startsWith  endsWith
 *
 * Compound rules:
 *   { "all": [ <rule>, … ] }   — logical AND
 *   { "any": [ <rule>, … ] }   — logical OR
 *   { "not": <rule> }          — logical NOT
 *
 * Request body:
 *   { "rule": <rule object>, "context": { … } }
 *
 * Response:
 *   200  { "result": true | false }
 *   400  { "error": "<reason>" }
 */

"use strict";

const express = require("express");

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Resolve a dot-separated field path against a plain object.
 *
 * resolveField("ctx.order.amount", { ctx: { order: { amount: 42 } } })
 * => 42
 *
 * Returns `undefined` for any missing segment so comparison operators can
 * handle it gracefully.
 */
function resolveField(path, ctx) {
  if (typeof path !== "string") return undefined;

  return path.split(".").reduce((node, key) => {
    if (node === undefined || node === null) return undefined;
    if (!Object.prototype.hasOwnProperty.call(node, key)) return undefined;
    return node[key];
  }, ctx);
}

/**
 * Validate that a field path contains only safe identifier characters so
 * callers cannot craft unexpected paths (e.g. prototype-pollution attempts
 * via "__proto__" or "constructor").
 */
const SAFE_FIELD_RE = /^[a-zA-Z_$][a-zA-Z0-9_$]*(\.[a-zA-Z_$][a-zA-Z0-9_$]*)*$/;

function isSafeField(path) {
  if (!SAFE_FIELD_RE.test(path)) return false;
  // Explicitly block dangerous prototype keys regardless of casing.
  const dangerous = new Set(["__proto__", "prototype", "constructor"]);
  return !path.split(".").some((seg) => dangerous.has(seg));
}

/**
 * Evaluate a single comparison rule node.
 *
 * @param {{ field: string, op: string, value: * }} node
 * @param {{ ctx: object }}                          evalCtx  — { ctx: <caller context> }
 * @returns {boolean}
 * @throws  {Error} on invalid structure / operator
 */
function evalComparison(node, evalCtx) {
  const { field, op, value } = node;

  if (typeof field !== "string" || field.trim() === "") {
    throw new Error(`Rule "field" must be a non-empty string, got: ${JSON.stringify(field)}`);
  }
  if (!isSafeField(field)) {
    throw new Error(`Rule "field" contains disallowed characters or reserved keys: ${field}`);
  }

  const ALLOWED_OPS = new Set(["==", "!=", ">", ">=", "<", "<=", "contains", "startsWith", "endsWith"]);
  if (!ALLOWED_OPS.has(op)) {
    throw new Error(
      `Unsupported operator "${op}". Allowed: ${[...ALLOWED_OPS].join(", ")}`
    );
  }

  const lhs = resolveField(field, evalCtx);

  switch (op) {
    case "==":         return lhs === value;
    case "!=":         return lhs !== value;
    case ">":          return lhs > value;
    case ">=":         return lhs >= value;
    case "<":          return lhs < value;
    case "<=":         return lhs <= value;
    case "contains":
      if (typeof lhs !== "string") {
        throw new Error(`Operator "contains" requires a string field, but "${field}" is ${typeof lhs}`);
      }
      return lhs.includes(String(value));
    case "startsWith":
      if (typeof lhs !== "string") {
        throw new Error(`Operator "startsWith" requires a string field, but "${field}" is ${typeof lhs}`);
      }
      return lhs.startsWith(String(value));
    case "endsWith":
      if (typeof lhs !== "string") {
        throw new Error(`Operator "endsWith" requires a string field, but "${field}" is ${typeof lhs}`);
      }
      return lhs.endsWith(String(value));
    default:
      // Unreachable given the ALLOWED_OPS guard above, but keeps linters happy.
      throw new Error(`Unhandled operator: ${op}`);
  }
}

/**
 * Recursively evaluate a rule node (comparison, all, any, or not).
 *
 * @param {*}             node     — rule node from request body
 * @param {{ ctx: object }} evalCtx — evaluation context
 * @returns {boolean}
 * @throws  {Error} on malformed rule
 */
function evalRule(node, evalCtx) {
  if (node === null || typeof node !== "object" || Array.isArray(node)) {
    throw new Error("Each rule node must be a plain object.");
  }

  // --- Compound: logical AND ---
  if (Object.prototype.hasOwnProperty.call(node, "all")) {
    const { all } = node;
    if (!Array.isArray(all) || all.length === 0) {
      throw new Error('"all" must be a non-empty array of rule nodes.');
    }
    return all.every((child) => evalRule(child, evalCtx));
  }

  // --- Compound: logical OR ---
  if (Object.prototype.hasOwnProperty.call(node, "any")) {
    const { any } = node;
    if (!Array.isArray(any) || any.length === 0) {
      throw new Error('"any" must be a non-empty array of rule nodes.');
    }
    return any.some((child) => evalRule(child, evalCtx));
  }

  // --- Compound: logical NOT ---
  if (Object.prototype.hasOwnProperty.call(node, "not")) {
    return !evalRule(node.not, evalCtx);
  }

  // --- Leaf: comparison ---
  if (
    Object.prototype.hasOwnProperty.call(node, "field") &&
    Object.prototype.hasOwnProperty.call(node, "op")
  ) {
    return evalComparison(node, evalCtx);
  }

  throw new Error(
    'Rule node must contain "field"+"op"+"value", "all", "any", or "not".'
  );
}

// ---------------------------------------------------------------------------
// POST /check
// ---------------------------------------------------------------------------

app.post("/check", (req, res) => {
  const { rule, context } = req.body ?? {};

  // --- Input validation ---
  if (rule === undefined) {
    return res.status(400).json({ error: 'Request body must include a "rule" field.' });
  }
  if (context === undefined || context === null || typeof context !== "object" || Array.isArray(context)) {
    return res.status(400).json({ error: 'Request body must include a "context" object.' });
  }

  // Build the evaluation context so field paths like "ctx.amount" resolve
  // correctly against the caller-supplied context object.
  const evalCtx = { ctx: context };

  let result;
  try {
    result = evalRule(rule, evalCtx);
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }

  return res.status(200).json({ result: Boolean(result) });
});

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`acme-rules listening on port ${PORT}`);
});

module.exports = app; // exported for testing

