/**
 * acme-rules — Rule Engine API
 *
 * POST /check
 *   Body: { "rule": "<expression>", "context": { ...fields } }
 *   Returns: { "result": true | false }
 *
 * SECURITY NOTE: docs/RULES_ENGINE.md proposes using `new Function()` / dynamic
 * eval to execute caller-supplied rule strings.  That approach is NOT used here
 * because it exposes the server to trivial Remote Code Execution (RCE): any
 * caller could send `process.exit(1)`, `require('fs').readFileSync(...)`, or any
 * other Node.js code and have it run with full server privileges.
 *
 * Instead, rule expressions are parsed into an AST and evaluated by a small,
 * explicit tree-walker that only supports the declared operator/operand set.
 * Any expression that falls outside that set is rejected with HTTP 400.
 */

'use strict';

const express = require('express');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluator
// ---------------------------------------------------------------------------

/**
 * Tokenise a rule expression string into an array of tokens.
 *
 * Supported token kinds:
 *   - number literals  : 42, 3.14
 *   - string literals  : 'hello', "world"
 *   - boolean literals : true, false
 *   - null literal     : null
 *   - identifiers      : foo, ctx
 *   - dot              : .
 *   - comparison ops   : ===, !==, ==, !=, <=, >=, <, >
 *   - logical ops      : &&, ||, !
 *   - parentheses      : ( )
 */
function tokenise(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    // Skip whitespace
    if (/\s/.test(expr[i])) { i++; continue; }

    // String literal (single or double quotes)
    if (expr[i] === '"' || expr[i] === "'") {
      const quote = expr[i++];
      let value = '';
      while (i < expr.length && expr[i] !== quote) {
        if (expr[i] === '\\') {
          i++;
          const escapes = { n: '\n', t: '\t', r: '\r', '\\': '\\', "'": "'", '"': '"' };
          value += escapes[expr[i]] ?? expr[i];
        } else {
          value += expr[i];
        }
        i++;
      }
      if (i >= expr.length) throw new SyntaxError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: 'string', value });
      continue;
    }

    // Number literal
    if (/[0-9]/.test(expr[i]) || (expr[i] === '-' && /[0-9]/.test(expr[i + 1] ?? ''))) {
      let raw = '';
      if (expr[i] === '-') raw += expr[i++];
      while (i < expr.length && /[0-9.]/.test(expr[i])) raw += expr[i++];
      tokens.push({ type: 'number', value: parseFloat(raw) });
      continue;
    }

    // Two-character operators
    const two = expr.slice(i, i + 2);
    if (['===', '!=='].includes(expr.slice(i, i + 3))) {
      tokens.push({ type: 'op', value: expr.slice(i, i + 3) });
      i += 3;
      continue;
    }
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }

    // Single-character operators / punctuation
    if ('<>!'.includes(expr[i])) { tokens.push({ type: 'op',   value: expr[i++] }); continue; }
    if (expr[i] === '.')         { tokens.push({ type: 'dot',  value: '.' });  i++; continue; }
    if (expr[i] === '(')         { tokens.push({ type: 'lparen' });             i++; continue; }
    if (expr[i] === ')')         { tokens.push({ type: 'rparen' });             i++; continue; }

    // Identifiers & keywords
    if (/[a-zA-Z_$]/.test(expr[i])) {
      let name = '';
      while (i < expr.length && /[a-zA-Z0-9_$]/.test(expr[i])) name += expr[i++];
      if (name === 'true')  { tokens.push({ type: 'boolean', value: true });  continue; }
      if (name === 'false') { tokens.push({ type: 'boolean', value: false }); continue; }
      if (name === 'null')  { tokens.push({ type: 'null',    value: null });  continue; }
      tokens.push({ type: 'ident', value: name });
      continue;
    }

    throw new SyntaxError(`Unexpected character: ${expr[i]}`);
  }

  return tokens;
}

/**
 * Parse a flat token array into an AST using a simple recursive-descent parser.
 *
 * Grammar (in order of increasing precedence):
 *
 *   expr       → or
 *   or         → and  ( '||' and  )*
 *   and        → cmp  ( '&&' cmp  )*
 *   cmp        → unary ( ( '==='|'!=='|'=='|'!='|'<'|'<='|'>'|'>=' ) unary )*
 *   unary      → '!' unary | primary
 *   primary    → literal | member | '(' expr ')'
 *   literal    → number | string | boolean | null
 *   member     → ident ( '.' ident )*
 */
function parse(tokens) {
  let pos = 0;

  function peek()    { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr()   { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    while (peek()?.type === 'op' && peek()?.value === '||') {
      consume();
      node = { type: 'logical', op: '||', left: node, right: parseAnd() };
    }
    return node;
  }

  function parseAnd() {
    let node = parseCmp();
    while (peek()?.type === 'op' && peek()?.value === '&&') {
      consume();
      node = { type: 'logical', op: '&&', left: node, right: parseCmp() };
    }
    return node;
  }

  const CMP_OPS = new Set(['===', '!==', '==', '!=', '<', '<=', '>', '>=']);

  function parseCmp() {
    let node = parseUnary();
    while (peek()?.type === 'op' && CMP_OPS.has(peek()?.value)) {
      const op = consume().value;
      node = { type: 'binary', op, left: node, right: parseUnary() };
    }
    return node;
  }

  function parseUnary() {
    if (peek()?.type === 'op' && peek()?.value === '!') {
      consume();
      return { type: 'unary', op: '!', operand: parseUnary() };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const token = peek();

    if (!token) throw new SyntaxError('Unexpected end of expression');

    // Grouped expression
    if (token.type === 'lparen') {
      consume();
      const node = parseExpr();
      if (peek()?.type !== 'rparen') throw new SyntaxError("Expected ')'");
      consume();
      return node;
    }

    // Literals
    if (token.type === 'number')  { consume(); return { type: 'literal', value: token.value }; }
    if (token.type === 'string')  { consume(); return { type: 'literal', value: token.value }; }
    if (token.type === 'boolean') { consume(); return { type: 'literal', value: token.value }; }
    if (token.type === 'null')    { consume(); return { type: 'literal', value: null }; }

    // Member expression: ctx.amount.subfield …
    if (token.type === 'ident') {
      consume();
      let node = { type: 'ident', name: token.value };
      while (peek()?.type === 'dot') {
        consume(); // consume '.'
        const prop = consume();
        if (!prop || prop.type !== 'ident') throw new SyntaxError('Expected property name after "."');
        node = { type: 'member', object: node, property: prop.value };
      }
      return node;
    }

    throw new SyntaxError(`Unexpected token: ${JSON.stringify(token)}`);
  }

  const ast = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after expression: ${JSON.stringify(tokens[pos])}`);
  }

  return ast;
}

/**
 * Walk the AST and evaluate it against the supplied context object.
 *
 * Only the node types produced by parse() above are handled; anything else
 * raises an error so the surface area stays explicit and auditable.
 */
function evalAst(node, ctx) {
  switch (node.type) {
    case 'literal':
      return node.value;

    case 'ident':
      // Only the root identifier 'ctx' is in scope — no global / process access.
      if (node.name !== 'ctx') {
        throw new ReferenceError(
          `Unknown identifier "${node.name}". Only "ctx" is in scope.`
        );
      }
      return ctx;

    case 'member': {
      const obj = evalAst(node.object, ctx);
      if (obj === null || obj === undefined) return undefined;
      if (typeof obj !== 'object') {
        throw new TypeError(`Cannot read property "${node.property}" of ${typeof obj}`);
      }
      return obj[node.property];
    }

    case 'unary':
      if (node.op === '!') return !evalAst(node.operand, ctx);
      throw new SyntaxError(`Unsupported unary operator: ${node.op}`);

    case 'binary': {
      // Evaluate both sides eagerly (short-circuit is handled in 'logical').
      const l = evalAst(node.left, ctx);
      const r = evalAst(node.right, ctx);
      switch (node.op) {
        case '===': return l === r;
        case '!==': return l !== r;
        case '==':  return l == r;   // eslint-disable-line eqeqeq
        case '!=':  return l != r;   // eslint-disable-line eqeqeq
        case '<':   return l <  r;
        case '<=':  return l <= r;
        case '>':   return l >  r;
        case '>=':  return l >= r;
        default:    throw new SyntaxError(`Unsupported binary operator: ${node.op}`);
      }
    }

    case 'logical': {
      const left = evalAst(node.left, ctx);
      if (node.op === '&&') return left ? evalAst(node.right, ctx) : left;
      if (node.op === '||') return left ? left : evalAst(node.right, ctx);
      throw new SyntaxError(`Unsupported logical operator: ${node.op}`);
    }

    default:
      throw new SyntaxError(`Unknown AST node type: ${node.type}`);
  }
}

/**
 * Public entry point: evaluate a rule expression string against a context object.
 * Returns a boolean, or throws SyntaxError / TypeError / ReferenceError on bad input.
 */
function evalRule(expr, ctx) {
  const tokens = tokenise(expr);
  const ast    = parse(tokens);
  return Boolean(evalAst(ast, ctx));
}

