    if (token.type === 'null')    { consume(); return { type: 'literal', value: null }; }

    // Member expression: ctx.amount.subfield …
    if (token.type === 'ident') {
      consume();
      let node = { type: 'ident', name: token.value };
      while (peek()?.type === 'dot') {
        consume(); // consume '.'
        const prop = consume();
        if (!prop || prop.type !== 'ident') throw new SyntaxError('Expected property name after "."');
        node = { type: 'member', object: node, property: prop.value };
      }
      return node;
    }

    throw new SyntaxError(`Unexpected token: ${JSON.stringify(token)}`);
  }

  const ast = parseExpr();

  if (pos < tokens.length) {
    throw new SyntaxError(`Unexpected token after expression: ${JSON.stringify(tokens[pos])}`);
  }

  return ast;
}

/**
 * Walk the AST and evaluate it against the supplied context object.
 *
 * Only the node types produced by parse() above are handled; anything else
 * raises an error so the surface area stays explicit and auditable.
 */
function evalAst(node, ctx) {
  switch (node.type) {
    case 'literal':
      return node.value;

    case 'ident':
      // Only the root identifier 'ctx' is in scope — no global / process access.
      if (node.name !== 'ctx') {
        throw new ReferenceError(
          `Unknown identifier "${node.name}". Only "ctx" is allowed as the root identifier.`
        );
      }
      return ctx;

    case 'member': {
      const obj = evalAst(node.object, ctx);
      if (obj === null || obj === undefined) return undefined;
      if (typeof obj !== 'object') {
        throw new TypeError(`Cannot read property "${node.property}" of ${typeof obj}`);
      }
      return obj[node.property];
    }

    case 'unary':
      if (node.op === '!') return !evalAst(node.operand, ctx);
      if (node.op === '-') return -evalAst(node.operand, ctx);
      throw new SyntaxError(`Unsupported unary operator: ${node.op}`);

    case 'binary': {
      const l = evalAst(node.left,  ctx);
      const r = evalAst(node.right, ctx);
      switch (node.op) {
        case '===': return l === r;
        case '!==': return l !== r;
        case '==':  return l == r;   // eslint-disable-line eqeqeq
        case '!=':  return l != r;   // eslint-disable-line eqeqeq
        case '<':   return l <  r;
        case '<=':  return l <= r;
        case '>':   return l >  r;
        case '>=':  return l >= r;
        default:    throw new SyntaxError(`Unsupported binary operator: ${node.op}`);
      }
    }

    case 'logical': {
      const left = evalAst(node.left, ctx);
      if (node.op === '&&') return left ? evalAst(node.right, ctx) : left;
      if (node.op === '||') return left ? left : evalAst(node.right, ctx);
      throw new SyntaxError(`Unsupported logical operator: ${node.op}`);
    }

    default:
      throw new SyntaxError(`Unknown AST node type: ${node.type}`);
  }
}

/**
 * Public entry point: evaluate a rule expression string against a context object.
 * Returns a boolean, or throws SyntaxError / TypeError / ReferenceError on bad input.
 */
function evalRule(expr, ctx) {
  const tokens = tokenise(expr);
  const ast    = parse(tokens);
  return Boolean(evalAst(ast, ctx));
}

// ---------------------------------------------------------------------------
// HTTP helpers
// ---------------------------------------------------------------------------

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type':   'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let raw = '';
    req.setEncoding('utf8');
    req.on('data', chunk => (raw += chunk));
    req.on('end',  () => resolve(raw));
    req.on('error', reject);
  });
}

// ---------------------------------------------------------------------------
// POST /check handler
// ---------------------------------------------------------------------------

async function handleCheck(req, res) {
  // Parse JSON body
  let body;
  try {
    const raw = await readBody(req);
    body = JSON.parse(raw);
  } catch {
    return sendJson(res, 400, { error: 'Request body must be valid JSON.' });
  }

  const { rule, context } = body ?? {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return sendJson(res, 400, {
      error: 'Missing or invalid "rule" field — expected a non-empty string.',
    });
  }

  if (context === undefined || context === null || typeof context !== 'object' || Array.isArray(context)) {
    return sendJson(res, 400, {
      error: 'Missing or invalid "context" field — expected a JSON object.',
    });
  }

  let result;
  try {
    result = evalRule(rule, context);
  } catch (err) {
    return sendJson(res, 400, {
      error: `Rule evaluation failed: ${err.message}`,
    });
  }

  return sendJson(res, 200, { result });
}

// ---------------------------------------------------------------------------
// HTTP server / router
// ---------------------------------------------------------------------------

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/check') {
    return handleCheck(req, res);
  }
  sendJson(res, 404, { error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Start server (skipped when required as a module, e.g. in tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  server.listen(PORT, () => console.log(`acme-rules listening on port ${PORT}`));
}

module.exports = { server, evalRule };

/**
 * Tests for POST /check and the safe rule evaluator.
 *
 * Run with:  node test.js
 */

'use strict';

const assert = require('assert/strict');
const http   = require('http');
const { server, evalRule } = require('./app');

// ---------------------------------------------------------------------------
// Tiny test runner
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✅  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ❌  ${label}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

function testThrows(label, fn) {
  try {
    fn();
    console.error(`  ❌  ${label}  (expected an error but none was thrown)`);
    failed++;
  } catch {
    console.log(`  ✅  ${label}`);
    passed++;
  }
}

// ---------------------------------------------------------------------------
// Unit tests — evalRule()
// ---------------------------------------------------------------------------

console.log('\n── evalRule() unit tests ──────────────────────────────────────────');

// Basic comparisons
test('ctx.amount > 100  (true)',   () => assert.equal(evalRule('ctx.amount > 100',   { amount: 200 }), true));
test('ctx.amount > 100  (false)',  () => assert.equal(evalRule('ctx.amount > 100',   { amount: 50  }), false));
test('ctx.amount >= 100 (equal)',  () => assert.equal(evalRule('ctx.amount >= 100',  { amount: 100 }), true));
test('ctx.amount < 100',           () => assert.equal(evalRule('ctx.amount < 100',   { amount: 99  }), true));
test('ctx.amount <= 99',           () => assert.equal(evalRule('ctx.amount <= 99',   { amount: 99  }), true));

// Strict equality
test('ctx.role === "admin" (true)',  () => assert.equal(evalRule('ctx.role === "admin"', { role: 'admin' }), true));
test('ctx.role === "admin" (false)', () => assert.equal(evalRule('ctx.role === "admin"', { role: 'user'  }), false));
test('ctx.role !== "admin"',         () => assert.equal(evalRule('ctx.role !== "admin"', { role: 'user'  }), true));

// Loose equality
test('ctx.code == 200  (coercion)', () => assert.equal(evalRule('ctx.code == 200',  { code: '200' }), true));
test('ctx.code != 404',             () => assert.equal(evalRule('ctx.code != 404',  { code: 200   }), true));

// Boolean literals & negation
test('ctx.active === true',   () => assert.equal(evalRule('ctx.active === true',  { active: true  }), true));
test('ctx.active === false',  () => assert.equal(evalRule('ctx.active === false', { active: false }), true));
test('!ctx.banned  (false)',  () => assert.equal(evalRule('!ctx.banned',          { banned: false }), true));
test('!ctx.banned  (true)',   () => assert.equal(evalRule('!ctx.banned',          { banned: true  }), false));

// Logical AND
test('ctx.amount > 50 && ctx.role === "admin" (true)',
  () => assert.equal(evalRule('ctx.amount > 50 && ctx.role === "admin"', { amount: 100, role: 'admin' }), true));
test('ctx.amount > 50 && ctx.role === "admin" (false)',
  () => assert.equal(evalRule('ctx.amount > 50 && ctx.role === "admin"', { amount: 10,  role: 'admin' }), false));

// Logical OR
test('ctx.amount > 50 || ctx.role === "admin" (short-circuit true)',
  () => assert.equal(evalRule('ctx.amount > 50 || ctx.role === "admin"', { amount: 10, role: 'admin' }), true));
test('ctx.amount > 50 || ctx.role === "admin" (both false)',
  () => assert.equal(evalRule('ctx.amount > 50 || ctx.role === "admin"', { amount: 10, role: 'user'  }), false));

// Parentheses / grouping
test('(ctx.a > 1) && (ctx.b < 5)',
  () => assert.equal(evalRule('(ctx.a > 1) && (ctx.b < 5)', { a: 2, b: 3 }), true));

// Nested property access
test('ctx.user.age >= 18',
  () => assert.equal(evalRule('ctx.user.age >= 18', { user: { age: 21 } }), true));
test('ctx.user.role === "editor"',
  () => assert.equal(evalRule('ctx.user.role === "editor"', { user: { role: 'editor' } }), true));

// null literal
test('ctx.token === null (true)',
  () => assert.equal(evalRule('ctx.token === null', { token: null  }), true));
test('ctx.token === null (false)',
  () => assert.equal(evalRule('ctx.token === null', { token: 'abc' }), false));

// Single-quoted strings
test("ctx.env === 'prod'",
  () => assert.equal(evalRule("ctx.env === 'prod'", { env: 'prod' }), true));

// Negative number literal
test('ctx.temp > -10  (true)',
  () => assert.equal(evalRule('ctx.temp > -10', { temp: 0 }), true));
test('ctx.temp > -10  (false)',
  () => assert.equal(evalRule('ctx.temp > -10', { temp: -20 }), false));

// Chained logical
test('ctx.a > 0 && ctx.b > 0 && ctx.c > 0  (all true)',
  () => assert.equal(evalRule('ctx.a > 0 && ctx.b > 0 && ctx.c > 0', { a: 1, b: 2, c: 3 }), true));
test('ctx.a > 0 && ctx.b > 0 && ctx.c > 0  (one false)',
  () => assert.equal(evalRule('ctx.a > 0 && ctx.b > 0 && ctx.c > 0', { a: 1, b: 2, c: 0 }), false));

// ---------------------------------------------------------------------------
// Security / rejection tests — evalRule()
// ---------------------------------------------------------------------------

console.log('\n── evalRule() security / rejection tests ──────────────────────────');

testThrows('Rejects unknown root identifier "process"',
  () => evalRule('process.exit', {}));
testThrows('Rejects unknown root identifier "require"',
  () => evalRule('require', {}));
testThrows('Rejects unknown root identifier "global"',
  () => evalRule('global.process', {}));
testThrows('Rejects unknown root identifier "Math"',
  () => evalRule('Math.max', {}));
testThrows('Rejects unknown root identifier in chained access',
  () => evalRule('process.env.SECRET > 0', {}));
testThrows('Rejects unterminated string literal',
  () => evalRule("ctx.name === 'open", {}));
testThrows('Rejects unexpected character (?)',
  () => evalRule('ctx.amount ??? 100', {}));
testThrows('Rejects leftover tokens after valid expression',
  () => evalRule('ctx.amount > 100 200', { amount: 50 }));

// ---------------------------------------------------------------------------
// Integration tests — POST /check over HTTP
// ---------------------------------------------------------------------------

console.log('\n── POST /check integration tests ───────────────────────────────────');

async function postTo(port, body) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req = http.request(
      {
        hostname: '127.0.0.1',
        port,
        path:     '/check',
        method:   'POST',
        headers:  { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
      },
      (res) => {
        let raw = '';
        res.on('data', chunk => (raw += chunk));
        res.on('end',  () => resolve({ status: res.statusCode, body: JSON.parse(raw) }));
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function itest(label, fn) {
  try {
    await fn();
    console.log(`  ✅  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ❌  ${label}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

async function runIntegration() {
  const port = await new Promise(resolve => {
    server.listen(0, '127.0.0.1', () => resolve(server.address().port));
  });

  const post = body => postTo(port, body);

  await itest('200 result:true  — ctx.amount > 100 (200)', async () => {
    const r = await post({ rule: 'ctx.amount > 100', context: { amount: 200 } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  await itest('200 result:false — ctx.amount > 100 (50)', async () => {
    const r = await post({ rule: 'ctx.amount > 100', context: { amount: 50 } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, false);
  });

  await itest('200 result:true  — ctx.role === "admin"', async () => {
    const r = await post({ rule: 'ctx.role === "admin"', context: { role: 'admin' } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  await itest('200 result:true  — nested ctx.user.age >= 18', async () => {
    const r = await post({ rule: 'ctx.user.age >= 18', context: { user: { age: 25 } } });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  await itest('200 result:true  — compound && rule', async () => {
    const r = await post({
      rule:    'ctx.amount > 50 && ctx.role === "admin"',
      context: { amount: 100, role: 'admin' },
    });
    assert.equal(r.status, 200);
    assert.equal(r.body.result, true);
  });

  await itest('400 when "rule" field is missing', async () => {
    const r = await post({ context: { amount: 100 } });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 when "rule" is an empty string', async () => {
    const r = await post({ rule: '  ', context: { amount: 100 } });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 when "context" field is missing', async () => {
    const r = await post({ rule: 'ctx.amount > 0' });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 when "context" is a string (not an object)', async () => {
    const r = await post({ rule: 'ctx.amount > 0', context: 'bad' });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 when "context" is an array (not a plain object)', async () => {
    const r = await post({ rule: 'ctx.amount > 0', context: [1, 2] });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 for RCE attempt — process.exit(1)', async () => {
    const r = await post({ rule: 'process.exit(1)', context: {} });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
    // Server must still be alive to answer subsequent requests
  });

  await itest('400 for RCE attempt — require("fs")', async () => {
    const r = await post({ rule: 'require("fs")', context: {} });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 for syntax error in rule', async () => {
    const r = await post({ rule: 'ctx.amount ???', context: { amount: 1 } });
    assert.equal(r.status, 400);
    assert.ok(r.body.error);
  });

  await itest('400 for malformed JSON body', async () => {
    const bad = '{rule: bad json}';
    const res = await new Promise((resolve, reject) => {
      const req = http.request(
        {
          hostname: '127.0.0.1',
          port,
          path:     '/check',
          method:   'POST',
          headers:  { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bad) },
        },
        (res) => {
          let raw = '';
          res.on('data', c => (raw += c));
          res.on('end',  () => resolve({ status: res.statusCode, body: JSON.parse(raw) }));
        }
      );
      req.on('error', reject);
      req.write(bad);
      req.end();
    });
    assert.equal(res.status, 400);
    assert.ok(res.body.error);
  });

  await itest('404 for unknown route GET /', async () => {
    const res = await new Promise((resolve, reject) => {
      http.get(`http://127.0.0.1:${port}/`, (res) => {
        let raw = '';
        res.on('data', c => (raw += c));
        res.on('end',  () => resolve({ status: res.statusCode, body: JSON.parse(raw) }));
      }).on('error', reject);
    });
    assert.equal(res.status, 404);
  });

  server.close(() => {
    console.log('\n────────────────────────────────────────────────────────────────────');
    console.log(`${passed} passed, ${failed} failed.`);
    if (failed > 0) {
      console.log('Some tests FAILED.\n');
      process.exitCode = 1;
    } else {
      console.log('All tests passed. ✓\n');
    }
  });
}

runIntegration().catch(err => {
  console.error('Integration test runner error:', err);
  process.exitCode = 1;
  server.close();
});

