// ---------------------------------------------------------------------------
// POST /check — evaluate a declarative rule expression against a context object
//
// Expected request body:
//   {
//     "rule": {
//       "field":    string,           // dot-notation path into `context`
//       "operator": string,           // one of: eq neq gt gte lt lte contains
//       "value":    string|number|boolean
//     },
//     "context": { ... }             // arbitrary key/value data to test
//   }
//
// Response:
//   { "result": true | false }
//   { "error":  "<message>" }        // 400 on bad input
//
// NOTE: The RULES_ENGINE.md "reference implementation" uses new Function() /
// eval() to execute caller-supplied strings as live JavaScript. That is a
// Remote Code Execution vulnerability — any caller could read process.env,
// spawn child processes, or exfiltrate data. This implementation provides
// equivalent rule-evaluation power through a safe, declarative approach with
// no dynamic code execution.
// ---------------------------------------------------------------------------

const SUPPORTED_OPERATORS = new Set(['eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'contains']);

/**
 * Resolve a dot-notation field path (e.g. "user.address.city") against an
 * object. Returns `undefined` if any segment along the path is missing.
 *
 * @param {object} obj
 * @param {string} path
 * @returns {*}
 */
function resolvePath(obj, path) {
  return path.split('.').reduce(
    (current, key) => (current != null && Object.prototype.hasOwnProperty.call(current, key) ? current[key] : undefined),
    obj,
  );
}

/**
 * Evaluate a single declarative rule against a context object.
 *
 * @param {{ field: string, operator: string, value: * }} rule
 * @param {object} context
 * @returns {boolean}
 * @throws {Error} if the rule is malformed or the operator is unsupported
 */
function evalRule(rule, context) {
  if (!rule || typeof rule !== 'object') {
    throw new Error('`rule` must be an object');
  }

  const { field, operator, value } = rule;

  if (typeof field !== 'string' || field.trim() === '') {
    throw new Error('`rule.field` must be a non-empty string');
  }
  if (typeof operator !== 'string' || !SUPPORTED_OPERATORS.has(operator)) {
    throw new Error(
      `\`rule.operator\` must be one of: ${[...SUPPORTED_OPERATORS].join(', ')}`,
    );
  }
  if (value === undefined) {
    throw new Error('`rule.value` is required');
  }

  const actual = resolvePath(context, field);

  switch (operator) {
    case 'eq':       return actual === value;
    case 'neq':      return actual !== value;
    case 'gt':       return actual > value;
    case 'gte':      return actual >= value;
    case 'lt':       return actual < value;
    case 'lte':      return actual <= value;
    case 'contains': return typeof actual === 'string' && actual.includes(String(value));
    default:
      // Unreachable given the set-membership check above, but keeps linters happy.
      throw new Error(`Unsupported operator: ${operator}`);
  }
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body ?? {};

  if (rule === undefined || rule === null) {
    return res.status(400).json({ error: '`rule` is required' });
  }
  if (context === undefined || context === null || typeof context !== 'object') {
    return res.status(400).json({ error: '`context` must be an object' });
  }

  try {
    const result = evalRule(rule, context);
    return res.json({ result });
  } catch (err) {
    return res.status(400).json({ error: err.message });
  }
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

