// Body: { "rule": <expression string>, "context": <object of variables> }
// Evaluates the rule expression against the provided context variables using a
// safe expression parser. Only arithmetic, comparison, and logical operators
// are supported — no access to Node.js built-ins, the filesystem, or the
// network is possible.
//
// Example request:
//   { "rule": "amount > 100 and status == \"active\"",
//     "context": { "amount": 150, "status": "active" } }
// Example response:
//   { "result": true }
app.post('/check', (req, res) => {
  const { rule, context } = req.body;

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: 'rule must be a non-empty string' });
  }

  if (context !== undefined && (typeof context !== 'object' || Array.isArray(context))) {
    return res.status(400).json({ error: 'context must be a plain object' });
  }

  const variables = context ?? {};

  let result;
  try {
    const parser = new Parser({
