const RULE_OPERATORS = {
  '>':          (a, b) => a > b,
  '<':          (a, b) => a < b,
  '>=':         (a, b) => a >= b,
  '<=':         (a, b) => a <= b,
  '==':         (a, b) => a == b,
  '===':        (a, b) => a === b,
  '!=':         (a, b) => a != b,
  '!==':        (a, b) => a !== b,
  'contains':   (a, b) => typeof a === 'string' && a.includes(b),
  'startsWith': (a, b) => typeof a === 'string' && a.startsWith(b),
  'endsWith':   (a, b) => typeof a === 'string' && a.endsWith(b),
