// Give the server a moment to bind, then run tests via the module's
// exported app directly using supertest-style inline HTTP.
const http = require('http');

function post(body) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req = http.request(
      { hostname: 'localhost', port: 3000, path: '/check', method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      (res) => {
        let buf = '';
        res.on('data', c => buf += c);
        res.on('end', () => resolve({ status: res.statusCode, body: JSON.parse(buf) }));
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function run() {
  const cases = [
    // happy-path: numeric comparison (true)
    { label: 'amount > 100 (true)',
      body:  { rule: { field: 'amount', operator: '>', value: 100 }, context: { amount: 250 } },
      want:  { status: 200, result: true } },
    // happy-path: numeric comparison (false)
    { label: 'amount > 100 (false)',
      body:  { rule: { field: 'amount', operator: '>', value: 100 }, context: { amount: 50 } },
      want:  { status: 200, result: false } },
    // happy-path: string contains
    { label: 'contains',
      body:  { rule: { field: 'name', operator: 'contains', value: 'Ali' }, context: { name: 'Alice' } },
      want:  { status: 200, result: true } },
    // happy-path: nested field
    { label: 'nested field',
      body:  { rule: { field: 'user.age', operator: '>=', value: 18 }, context: { user: { age: 21 } } },
      want:  { status: 200, result: true } },
    // error: missing rule
    { label: 'missing rule → 400',
      body:  { context: { amount: 10 } },
      want:  { status: 400 } },
    // error: bad operator
    { label: 'bad operator → 400',
      body:  { rule: { field: 'x', operator: 'eval', value: 1 }, context: { x: 1 } },
      want:  { status: 400 } },
    // security: path with __proto__ blocked
    { label: '__proto__ path blocked → 400',
      body:  { rule: { field: '__proto__', operator: '==', value: 1 }, context: {} },
      want:  { status: 400 } },
    // security: no arbitrary code execution possible (operator 'eval' is rejected above)
  ];

  let passed = 0;
  for (const tc of cases) {
    const res = await post(tc.body);
    const ok  = res.status === tc.want.status &&
                (tc.want.result === undefined || res.body.result === tc.want.result);
    console.log((ok ? '✅' : '❌'), tc.label, '→', JSON.stringify(res.body));
    if (ok) passed++;
  }
  console.log(\`\n\${passed}/\${cases.length} tests passed\`);
  process.exit(passed === cases.length ? 0 : 1);
}

setTimeout(run, 200);
